<template>
  <div class="container users-page">
    <div class="row mt-15 mb-25 justify-between users-page-toolbar">
      <div class="col-sm-6 col-md-6 col-lg-6">
        <q-input
          v-model="filter.keyword"
          dense
          autofocus
          @update:model-value="debouncedSearch"
          :placeholder="$t('search')"
          outlined
          @keyup.enter="onSearchEnter"
        />
      </div>
      <div class="row q-gutter-sm">
        <f-btn
          icon="show_chart"
          :label="$t('login_analytics')"
          appearance="outline"
          @click="$router.push('/settings/login-analytics')"
        />
        <f-btn
          :label="$t('add_user')"
          @click="openForm(null)"
        />
      </div>
    </div>

    <div class="full-width users-page-table">
      <DocBitsTable
        :rows="usersList"
        :columns="columns"
        :loading="isLoading"
        row-key="id"
        table-id="users_table"
        :features="{
          sorting: true,
          clientSideSort: true,
          filtering: false,
          selection: false,
          bulkActions: false,
          rowActions: true,
          resizable: false,
          pagination: false,
          columnReorder: true,
          columnSettings: false,
          stickyFirstColumn: false,
          stickyLastColumn: true,
        }"
        :row-actions="rowActions"
        :column-order="columnOrder"
        no-data-label="no_record_found"
        table-class="full-height"
        flat-style
        @row-click="handleRowClick"
        @row-action="handleRowAction"
        @column-reorder="handleColumnReorder"
      >
        <template #body-cell-name="{ row }">
          {{ row.name }}
        </template>

        <!-- Email column -->
        <template #body-cell-email="{ row }">
          {{ row.email }}
        </template>

        <!-- Last logged in: format date -->
        <template #body-cell-last_logged_in="{ row }">
          {{ formatDateAccordingToPreference(row.last_logged_in) }}
        </template>

        <!-- Is admin checkbox (editable) -->
        <template #body-cell-is_organisation_admin="{ row }">
          <q-checkbox
            dense
            v-model="row.is_organisation_admin"
            @click.stop="isAdminToggle(row.id, row.is_organisation_admin)"
          />
        </template>

        <!-- Is system user checkbox (disabled) -->
        <template #body-cell-is_system_user="{ row }">
          <q-checkbox
            dense
            :model-value="!!row.is_system_user"
            disabled
          />
        </template>

        <!-- Is active checkbox (disabled) -->
        <template #body-cell-is_active="{ row }">
          <q-checkbox
            dense
            :model-value="row.is_active !== false"
            disabled
          />
        </template>
      </DocBitsTable>
    </div>
  </div>
  <Loader />

  <UserFormDialog
    v-model="userDialog"
    :user="editingUser"
    @saved="onUserSaved"
  />

  <q-dialog v-model="confirmDelete" persistent>
    <q-card style="min-width: 500px; max-width: 600px; border-radius: 12px">
      <!-- Warning Icon Header -->
      <q-card-section class="row justify-center q-pt-lg q-pb-md">
        <div class="warning-icon-container">
          <q-icon name="warning" size="80px" color="negative" />
        </div>
      </q-card-section>

      <!-- Title -->
      <q-card-section class="q-pt-none q-pb-sm text-center">
        <div class="text-h5 text-weight-medium">
          {{ $t('delete_user_confirm_title', { name: getUserName() }) }}
        </div>
      </q-card-section>

      <!-- Description -->
      <q-card-section class="q-pt-none q-pb-lg text-center">
        <div class="text-body1 text-grey-8" style="line-height: 1.6">
          {{ $t('delete_user_confirm_desc') }}
        </div>
      </q-card-section>

      <!-- Actions -->
      <q-card-actions align="center" class="q-px-lg q-pb-lg q-gutter-sm">
        <f-btn
          :label="$t('cancel')"
          appearance="cancel"
          v-close-popup
          style="min-width: 140px"
        />
        <f-btn
          :label="$t('delete_user')"
          appearance="negative"
          v-close-popup
          @click="deleteUser()"
          style="min-width: 140px"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import cache from 'src/utils/cache';
import dateUtils from 'src/utils/date';
import { CONSTANTS } from 'src/constants';
import { dynamicObj } from '../../assets';
import { getUserRequest } from 'src/types';
import Loader from 'components/Loader.vue';
import { useUserStore } from 'src/store/main';
import helperUtil from 'src/utils/helperUtil';
import { userApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions';
import helperMixin from 'src/mixins/helperMixin';
import { DocBitsTable } from 'src/components/Table';
import { debounce } from 'quasar';
import { defineComponent, ref, computed } from 'vue';
import { notify } from 'src/components/notifications/notify';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import UserFormDialog from 'src/components/Settings/Users/UserFormDialog.vue';
import type {
  UnifiedTableColumn,
  RowActionItem,
  RowActionPayload,
} from 'src/components/Table';
import { useTranslate } from '@tolgee/vue';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin, helperUtil, cache, dateUtils],
  data() {
    return {
      userDialog: ref(false),
      editingUser: null as any,
      debouncedSearch: debounce((_value: any) => {}, 1000) as ReturnType<
        typeof debounce
      >,
    };
  },
  created() {
    this.debouncedSearch = debounce((value: any) => {
      this.updateSearch(value);
    }, 1000);
  },
  components: {
    DocBitsTable,
    Loader,
    UserFormDialog,
  },
  mounted() {
    this.init();
    document.addEventListener('apply_filters', this.applyFilterEvent);
  },
  unmounted() {
    document.removeEventListener('apply_filters', this.applyFilterEvent);
    this.debouncedSearch?.cancel();
  },
  methods: {
    async init() {
      await this.getUsers(true);
      this.prepareColumns();

      // Check for edit query param and auto-open edit dialog
      const editUserId = this.$route.query.edit;
      if (editUserId) {
        // Find user by ID in the loaded users list (use allUsers from store)
        const user = this.allUsers.find((u: any) => u.id === editUserId);
        if (user) {
          // Open edit dialog for this user
          this.openForm(user);
        }
        // Clear query param from URL after opening dialog
        this.$router.replace({ query: {} });
      }
    },
    async isAdminToggle(userId: any, value: any) {
      this.showLoading();
      try {
        let formData = new FormData();
        formData.append('is_organisation_admin', value ? '1' : '0');
        formData.append('org_id', getOrgId());
        const response = await userApiService.editUser(userId, formData);
        if (response?.success === false) {
          notify.error(ApiExceptions.getErrorMessage(response));
        } else {
          notify.success(this.$t('user_updated'));
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        await this.getUsers(false);
        this.hideLoading();
        return;
      }
    },
    async getUsers(showLoader: boolean) {
      this.isLoading = true;
      if (showLoader) {
        this.showLoading();
      }
      try {
        const queryParam = this.generateQueryParams(this.filter);
        // Clear cached users before fetching new data
        this.allUsers = [];
        await this.fetchAllUsers(queryParam);
        this.usersList = this.allUsers.map((u: any) => ({
          ...u,
          name: `${u.first_name || ''} ${u.last_name || ''}`.trim(),
        }));
        // Ensure store list is cleared if filters are applied
        if (queryParam) {
          this.restUserPromise();
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.isLoading = false;
        if (showLoader) {
          this.hideLoading();
        }
      }
    },
    generateQueryParams(filter: Record<string, any>) {
      // Client-side pagination - fetch all users, no limit/skip params needed
      return Object.entries(filter)
        .filter(([_, value]) => value)
        .map(([key, value]) => `${key}=${encodeURIComponent(value)}`)
        .join('&');
    },
    openForm(user: any) {
      this.editingUser = user || null;
      this.userDialog = true;
    },
    async onUserSaved() {
      await this.getUsers(false);
    },
    async deleteUser() {
      this.showLoading();
      try {
        const response = await userApiService.deleteUser(this.userId);

        if (!response?.success) {
          throw response;
        }

        this.userId = null;
        await this.getUsers(false);
        notify.success(this.$t('user_deleted'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.confirmDelete = false;
        this.hideLoading();
      }
    },
    updateSearch(value: any) {
      this.filter.keyword = value;
      this.getUsers(true);
    },
    onSearchEnter() {
      this.debouncedSearch.cancel();
      this.updateSearch(this.filter.keyword);
    },
    applyFilterEvent(ev: any) {
      this.filter = {
        keyword: '',
        sort_by: ev.detail.orderBy['field_name'],
        order: ev.detail.orderBy['direction'],
      };
      this.getUsers(true);
    },
    prepareColumns() {
      const savedOrderString = this.getDataByKey(CONSTANTS.users_columns_order);
      if (!savedOrderString) return;

      const savedOrder = JSON.parse(savedOrderString as string);
      this.columnOrder = savedOrder;
    },
    handleColumnReorder(newOrder: string[]) {
      this.columnOrder = newOrder;
      this.setDataToLocalStorage(
        CONSTANTS.users_columns_order,
        JSON.stringify(newOrder),
      );
    },
    handleRowAction(payload: RowActionPayload) {
      if (payload.action === 'edit') {
        this.openForm(payload.row);
      } else if (payload.action === 'delete') {
        this.userId = payload.rowId;
        this.confirmDelete = true;
      }
    },
    handleRowClick(payload: { row: any }) {
      this.$router.push(`/settings/user/${payload.row.id}`);
    },
    getUserName() {
      const user = this.allUsers.find((u: any) => u.id === this.userId);
      return user ? `${user.first_name} ${user.last_name}` : 'User';
    },
  },
  setup() {
    // Initialize Pinia store for user data
    const user_store = useUserStore();
    const { fetchAllUsers, restUserPromise } = user_store;
    const { allUsers } = storeToRefs(user_store);

    const { t } = useTranslate();
    // Column definitions for DocBitsTable (with translated labels)
    const columns = computed<UnifiedTableColumn[]>(() => [
      {
        name: 'name',
        label: t.value('name'),
        field: 'name',
        sortable: true,
        align: 'left',
      },
      {
        name: 'email',
        label: t.value('email'),
        field: 'email',
        sortable: true,
        align: 'left',
      },
      {
        name: 'last_logged_in',
        label: t.value('last_login'),
        field: 'last_logged_in',
        sortable: false,
        align: 'left',
      },
      {
        name: 'is_organisation_admin',
        label: t.value('is_admin'),
        field: 'is_organisation_admin',
        sortable: true,
        align: 'left',
      },
      {
        name: 'is_system_user',
        label: t.value('is_system_admin'),
        field: 'is_system_user',
        sortable: true,
        align: 'left',
      },
      {
        name: 'is_active',
        label: t.value('active'),
        field: 'is_active',
        sortable: true,
        align: 'left',
      },
    ]);

    // Row actions for edit and delete
    const rowActions: RowActionItem[] = [
      {
        key: 'edit',
        label: 'edit',
        icon: 'edit',
        color: 'primary',
      },
      {
        key: 'delete',
        label: 'delete',
        icon: 'delete',
        color: 'negative',
        separator: true,
      },
    ];

    return {
      columns,
      rowActions,
      columnOrder: ref<string[]>([]),
      userId: ref(),
      confirmDelete: ref(false),
      filter: ref<getUserRequest>({ keyword: '' }),
      // Store references
      fetchAllUsers,
      restUserPromise,
      allUsers,
      usersList: ref([] as any),
      isLoading: ref(false),
      t,
    };
  },
});
</script>

